    if x['id']=='gabriel-zamora-post-doubles':
        x['code']="post[post['id'].eq(8)].sort_values('days')['value'].agg(['first','last']).to_frame('value').assign(ratio=lambda d: d.loc['last','value']/d.loc['first','value'])"
    if x['id']=='laura-lee-post-decline':
        x['code']="post[post['id'].eq(18)].sort_values('days')['value'].agg(['first','last']).to_frame('value').assign(change=lambda d: d.loc['last','value']/d.loc['first','value'] - 1)"
    if x['id']=='jaclyn-hill-more-dislikes':
        x['code']="people.loc[people['name'].eq('Jaclyn Hill'), 'likes_dislikes_views'].str.split('/', expand=True).iloc[:, :2].set_axis(['likes','dislikes'], axis=1).astype(float).assign(like_share=lambda d: d['likes']/(d['likes']+d['dislikes'])).iloc[0]"
json.dump(f,open('facts.json','w'),indent=1,ensure_ascii=False)
